document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("html-input"),r=document.getElementById("html-preview"),t=document.getElementById("html-form");t&&(n.addEventListener("input",()=>{r.innerHTML=n.value}),t.addEventListener("submit",async t=>{t.preventDefault();const r=n.value,i=document.getElementById("loader-overlay");try{i.classList.remove("d-none");const t=await fetch(apiUrlwithHtml,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({html:r})});if(!t.ok)throw new Error("Failed to generate PDF");const f=await t.blob(),u=window.URL.createObjectURL(f),n=document.createElement("a");n.href=u;n.download="document.pdf";document.body.appendChild(n);n.click();n.remove();window.URL.revokeObjectURL(u)}catch(u){alert("Error: "+u.message)}finally{i.classList.add("d-none")}}));const i=document.getElementById("url-form"),u=document.getElementById("url-input");i&&i.addEventListener("submit",async n=>{n.preventDefault();const i=u.value.trim();if(!i){alert("Please enter a valid URL.");return}const t=document.getElementById("loader-overlay");try{t&&t.classList.remove("d-none");const r=await fetch(apiUrlwithUrl,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url:i})});if(!r.ok)throw new Error("Failed to generate PDF");const f=await r.blob(),u=window.URL.createObjectURL(f),n=document.createElement("a");n.href=u;n.download="webpage.pdf";document.body.appendChild(n);n.click();n.remove();window.URL.revokeObjectURL(u)}catch(r){alert("Error: "+r.message)}finally{t&&t.classList.add("d-none")}})});